    def test_wikidata_loads_entity_for_author_with_wikidata_id(self):
        author = models.Author(
            MockSite(), '/authors/OL1A', data={'remote_ids': {'wikidata': 'Q42'}}
        )
        with patch.object(models, 'get_wikidata_entity', return_value='entity') as get_entity:
